<div class="page-heading"><div><span class="eyebrow text-teal">YOUR PEOPLE</span><h1>บัญชีสตาฟ</h1><p>ดูแลบัญชี บทบาท และค่ายที่ทีมงานเข้าถึงได้</p></div><a class="button primary" href="<?= e(url('staff-edit')) ?>">+ เพิ่มบัญชีสตาฟ</a></div><section class="panel"><div class="section-heading"><h2>ทีมงานทั้งหมด <span class="count"><?= count($staff) ?></span></h2></div><div class="table-wrap"><table><thead><tr><th>ทีมงาน</th><th>บทบาท</th><th>สถานะบัญชี</th><th>จัดการ</th></tr></thead><tbody><?php foreach($staff as $member): ?><tr><td><strong><?= e($member['name']) ?></strong><?php if($member['id']===$user['id']): ?> <span class="count">คุณ</span><?php endif ?><?php if(!empty($member['student_id'])): ?><small>รหัสนักศึกษา <?= e($member['student_id']) ?></small><?php endif ?><small><?= e($member['email']??'ยังไม่ระบุอีเมล') ?></small><?php if(isset($passwordRequests[$member['id']])): ?><span class="badge draft">ขอตั้งรหัสผ่านใหม่</span><?php endif ?></td><td><?= e(role_label($member['role'])) ?></td><td><span class="badge <?= $member['is_active']?'active':'cancelled' ?>"><?= $member['is_active']?(!empty($member['needs_setup'])?'รอตั้งค่าโปรไฟล์':'เปิดใช้งาน'):'ปิดใช้งาน' ?></span></td><td><a class="text-link" href="<?= e(url('staff-edit',['id'=>$member['id']])) ?>">แก้ไข →</a> <?= delete_link('staff',(int)$member['id']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
